!== 'passed') return failed()\n      }\n      return 'succeeded'\n    } catch {\n      return failed()\n    }\n  }\n\n  private prunePlans(): void {\n    const now = this.now()\n    for (const [id, stored] of this.plans) {\n      if (Date.parse(stored.plan.expiresAt ?? '') <= now) this.plans.delete(id)\n    }\n  }\n\n  async close(): Promise<void> {\n    this.disposed = true\n    this.plans.clear()\n    await this.operation\n  }\n}\n"
